import{_ as t,o as d,c as n,a3 as o}from"./chunks/framework.WnkSrLAX.js";const m=JSON.parse('{"title":"Anhang: Docker-Befehle","description":"","frontmatter":{},"headers":[],"relativePath":"anhang-docker.md","filePath":"anhang-docker.md"}'),a={name:"anhang-docker.md"};function r(c,e,i,l,s,h){return d(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="anhang-docker-befehle" tabindex="-1">Anhang: Docker-Befehle <a class="header-anchor" href="#anhang-docker-befehle" aria-label="Permalink to &quot;Anhang: Docker-Befehle&quot;">​</a></h1><p>Befehle und Optionen aus den Übungen an Tag 1. <code>api</code> steht für einen Containernamen.</p><h2 id="container-starten" tabindex="-1">Container starten <a class="header-anchor" href="#container-starten" aria-label="Permalink to &quot;Container starten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Befehl bzw. Option</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>docker run &lt;image&gt;</code></td><td>Container aus einem Image erzeugen und starten; fehlt das Image lokal, wird es zuerst geladen</td></tr><tr><td><code>-d</code></td><td>im Hintergrund starten; die Eingabeaufforderung kehrt sofort zurück, die Ausgabe zeigt <code>docker logs</code></td></tr><tr><td><code>--name api</code></td><td>fester Name; ohne die Option vergibt Docker einen zufälligen Namen</td></tr><tr><td><code>-e NAME=wert</code></td><td>Umgebungsvariable im Container setzen</td></tr><tr><td><code>-p 8090:8080</code></td><td>Port 8090 des Rechners auf Port 8080 im Container weiterleiten (Rechner:Container)</td></tr><tr><td><code>-v api-logs:/var/log/app</code></td><td>benanntes Volume <code>api-logs</code> unter <code>/var/log/app</code> einbinden</td></tr><tr><td><code>-v ${PWD}\\logs:/var/log/app</code></td><td>Verzeichnis <code>logs</code> im aktuellen Verzeichnis einbinden (Bind Mount, PowerShell)</td></tr><tr><td><code>--rm</code></td><td>Container nach dem Ende automatisch entfernen</td></tr></tbody></table><h2 id="container-untersuchen-und-verwalten" tabindex="-1">Container untersuchen und verwalten <a class="header-anchor" href="#container-untersuchen-und-verwalten" aria-label="Permalink to &quot;Container untersuchen und verwalten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Befehl bzw. Option</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>docker ps</code></td><td>laufende Container</td></tr><tr><td><code>docker ps -a</code></td><td>alle Container, auch beendete, mit Status und Exit-Code</td></tr><tr><td><code>docker logs api</code></td><td>Standardausgabe und Fehlerausgabe des Containers</td></tr><tr><td><code>docker exec api &lt;befehl&gt;</code></td><td>einen Befehl im laufenden Container ausführen</td></tr><tr><td><code>docker exec -it api sh</code></td><td>Shell im laufenden Container; <code>-i</code> hält die Eingabe offen, <code>-t</code> stellt ein Terminal bereit; <code>exit</code> beendet die Shell</td></tr><tr><td><code>docker diff api</code></td><td>Änderungen im Dateisystem gegenüber dem Image (<code>A</code> hinzugefügt, <code>C</code> geändert, <code>D</code> gelöscht)</td></tr><tr><td><code>docker stop api</code> / <code>docker start api</code></td><td>Container anhalten bzw. wieder starten; der Inhalt bleibt erhalten</td></tr><tr><td><code>docker rm api</code></td><td>beendeten Container entfernen</td></tr><tr><td><code>docker rm -f api</code></td><td>Container entfernen, auch wenn er läuft (<code>-f</code> = force)</td></tr></tbody></table><h2 id="images-und-volumes" tabindex="-1">Images und Volumes <a class="header-anchor" href="#images-und-volumes" aria-label="Permalink to &quot;Images und Volumes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Befehl bzw. Option</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>docker history &lt;image&gt;</code></td><td>Schichten des Images mit den Anweisungen, aus denen sie entstanden sind</td></tr><tr><td><code>docker image inspect &lt;image&gt; --format &quot;…&quot;</code></td><td>Metadaten des Images; <code>--format</code> wählt einzelne Felder aus</td></tr><tr><td><code>docker volume rm api-logs</code></td><td>Volume löschen; nur möglich, wenn kein Container es verwendet</td></tr></tbody></table><h2 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to &quot;Docker Compose&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Befehl bzw. Option</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>docker compose up -d</code></td><td>alle Dienste aus <code>compose.yaml</code> im aktuellen Verzeichnis im Hintergrund starten</td></tr><tr><td><code>docker compose up -d --scale api=2</code></td><td>wie oben, Dienst <code>api</code> mit zwei Instanzen</td></tr><tr><td><code>docker compose ps</code></td><td>Container des Projekts mit Status</td></tr><tr><td><code>docker compose down -v</code></td><td>Container und Netzwerk entfernen, mit <code>-v</code> auch die Volumes</td></tr></tbody></table><h2 id="haufige-meldungen" tabindex="-1">Häufige Meldungen <a class="header-anchor" href="#haufige-meldungen" aria-label="Permalink to &quot;Häufige Meldungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Meldung</th><th>Ursache und Abhilfe</th></tr></thead><tbody><tr><td><code>Conflict. The container name &quot;/api&quot; is already in use</code></td><td>Ein Container mit diesem Namen existiert noch; <code>docker rm -f api</code></td></tr><tr><td><code>ports are not available</code> bzw. <code>port is already allocated</code></td><td>Der linke Port bei <code>-p</code> ist auf dem Rechner belegt; einen anderen wählen</td></tr><tr><td><code>No such container</code></td><td>Name falsch geschrieben oder Container bereits entfernt; <code>docker ps -a</code></td></tr></tbody></table>',12)])])}const g=t(a,[["render",r]]);export{m as __pageData,g as default};
